using AwesomeAssertions;
using PolyTerm.App.Import;
using Xunit;

namespace PolyTerm.App.Tests;

/// <summary>
/// Verifies <see cref="MRemoteNgPasswordCrypto"/> against a test vector generated by an independent
/// PyCryptodome implementation of mRemoteNG's documented AEAD scheme (PBKDF2-HMAC-SHA1/1000 iterations,
/// AES-256-GCM, 16-byte salt+nonce, salt as AAD) — not just a self-consistent round-trip of this same
/// code, since that alone wouldn't prove compatibility with real mRemoteNG output.
/// </summary>
public sealed class MRemoteNgPasswordCryptoTests
{
    // Generated independently via pycryptodome (see scratch script, not checked in) using mRemoteNG's
    // documented algorithm: password "mR3m", plaintext "Sup3rSecretPassw0rd!".
    private const string KnownCipherText =
        "8T0xN+tYMK56n7qEfT+8EvnRyZLHE/Fwars0CVA3adEUCH8hzkvtWIqvsFxeWkkieL+p3syA0/4JZZ6r2No4JqTwn8A=";

    [Fact]
    public void TryDecrypt_DecryptsAnIndependentlyGeneratedVector_WithTheDefaultMasterPassword()
    {
        var result = MRemoteNgPasswordCrypto.TryDecrypt(KnownCipherText, "mR3m");

        result.Should().Be("Sup3rSecretPassw0rd!");
    }

    [Fact]
    public void TryDecrypt_ReturnsNull_WhenMasterPasswordIsWrong()
    {
        var result = MRemoteNgPasswordCrypto.TryDecrypt(KnownCipherText, "wrong-password");

        result.Should().BeNull();
    }

    [Fact]
    public void TryDecrypt_RoundTrips_ThroughThisImplementationsOwnEncrypt()
    {
        // Self round-trip using this file's own crypto primitives (BouncyCastle GCM), independent of
        // the cross-library vector above — catches regressions in the encrypt-side test helper below.
        var blob = EncryptForTest("hello world", "correct horse battery staple");

        MRemoteNgPasswordCrypto.TryDecrypt(blob, "correct horse battery staple").Should().Be("hello world");
    }

    [Fact]
    public void TryDecrypt_ReturnsEmptyString_ForEmptyInput()
    {
        MRemoteNgPasswordCrypto.TryDecrypt("", "mR3m").Should().Be("");
    }

    [Theory]
    [InlineData("not-valid-base64!!!")]
    [InlineData("dG9vc2hvcnQ=")] // valid base64, but far too short to contain salt+nonce+tag
    public void TryDecrypt_ReturnsNull_ForMalformedInput(string malformed)
    {
        MRemoteNgPasswordCrypto.TryDecrypt(malformed, "mR3m").Should().BeNull();
    }

    // Mirrors mRemoteNG's own AeadCryptographyProvider.SimpleEncrypt exactly (random salt/nonce, salt
    // as AAD, tag appended to ciphertext) so the round-trip test exercises the real blob layout.
    private static string EncryptForTest(string plainText, string password)
    {
        var salt = new byte[16];
        var nonce = new byte[16];
        System.Security.Cryptography.RandomNumberGenerator.Fill(salt);
        System.Security.Cryptography.RandomNumberGenerator.Fill(nonce);

        var passwordBytes = Org.BouncyCastle.Crypto.PbeParametersGenerator.Pkcs5PasswordToBytes(password.ToCharArray());
        var generator = new Org.BouncyCastle.Crypto.Generators.Pkcs5S2ParametersGenerator(new Org.BouncyCastle.Crypto.Digests.Sha1Digest());
        generator.Init(passwordBytes, salt, 1000);
        var key = ((Org.BouncyCastle.Crypto.Parameters.KeyParameter)generator.GenerateDerivedMacParameters(256)).GetKey();

        var cipher = new Org.BouncyCastle.Crypto.Modes.GcmBlockCipher(new Org.BouncyCastle.Crypto.Engines.AesEngine());
        cipher.Init(true, new Org.BouncyCastle.Crypto.Parameters.AeadParameters(new Org.BouncyCastle.Crypto.Parameters.KeyParameter(key), 128, nonce, salt));

        var plainBytes = System.Text.Encoding.UTF8.GetBytes(plainText);
        var cipherText = new byte[cipher.GetOutputSize(plainBytes.Length)];
        var len = cipher.ProcessBytes(plainBytes, 0, plainBytes.Length, cipherText, 0);
        len += cipher.DoFinal(cipherText, len);

        var blob = new byte[salt.Length + nonce.Length + len];
        Buffer.BlockCopy(salt, 0, blob, 0, salt.Length);
        Buffer.BlockCopy(nonce, 0, blob, salt.Length, nonce.Length);
        Buffer.BlockCopy(cipherText, 0, blob, salt.Length + nonce.Length, len);

        return Convert.ToBase64String(blob);
    }
}
